// SPDX-License-Identifier: MIT
// Oeeoo Coin — libFuzzer harnesses, shared helpers (Milestone 18).
// Each harness in this directory defines LLVMFuzzerTestOneInput
// and links against the coverage-instrumented oeeoo_core_fuzz
// library. The harnesses are pure parsers plus cheap validation:
// they never touch the network, the disk (except fuzz_wallet,
// which rewrites one scratch file), or the wall clock, so a run
// is deterministic for a fixed seed. Valid inputs come from the
// seed corpus in tests/fuzz/corpus/ (generated by
// tests/fuzz/gen_corpus.cpp); libFuzzer mutates from there.
#pragma once

#include <cstdint>
#include <vector>

#include "blockchain/block.h"
#include "crypto/ecdsa.h"
#include "mining/miner.h"
#include "script/script.h"
#include "transactions/sighash.h"
#include "transactions/transaction.h"

namespace oeeoo {
namespace fuzz {

// A fixed keypair, generated once per process (never per input:
// key generation costs milliseconds and would dominate the run).
inline const KeyPair& FuzzKey() {
  static const KeyPair key = [] {
    KeyPair k;
    GenerateKeyPair(k);
    return k;
  }();
  return key;
}

inline std::vector<unsigned char> FuzzSpk() {
  return CreateP2PKHScriptPubKey(PubKeyHash160(FuzzKey().pubkey));
}

// A valid, signed P2PKH spend of a fake 50-coin output. Used as
// the base input for the tx/script harnesses.
inline Transaction ValidTx() {
  Transaction tx;
  tx.version = 1;
  TxIn in;
  in.prevTxHash.fill(0x55);
  in.prevOutIndex = 0;
  in.sequence = 0xffffffff;
  tx.vin.push_back(in);
  TxOut out;
  out.value = 49 * COIN;
  out.scriptPubKey = FuzzSpk();
  tx.vout.push_back(out);
  tx.lockTime = 0;
  Hash256 h;
  if (LegacySighash(tx, 0, FuzzSpk(), kSigHashAll, h)) {
    std::vector<unsigned char> sig = SignHash(h, FuzzKey().privkey);
    sig.push_back(static_cast<unsigned char>(kSigHashAll));
    tx.vin[0].scriptSig = CreateP2PKHScriptSig(sig, FuzzKey().pubkey);
  }
  return tx;
}

// A valid block: one coinbase, correct Merkle root. (Proof of work
// is NOT done: the harnesses test parsing and CheckBasic, and no
// fuzzer can produce valid PoW — the same caveat Bitcoin Core
// documents for its own fuzz targets.)
inline Block ValidBlock() {
  Block block;
  block.header.nVersion = 1;
  block.header.nTime = 1700000000;
  block.header.nBits = 0x207fffff;
  block.vtx = {CreateCoinbase(0, FuzzSpk(), 0, "x")};
  block.header.hashMerkleRoot = block.ComputeMerkleRoot();
  return block;
}

}  // namespace fuzz
}  // namespace oeeoo
